 const head=(eyebrow:string,title:string,subtitle:string,action?:string,handle?:()=>void)=><header className="mw-head"><div><span className="mw-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action&&<Button onClick={handle||(()=>openComposer())}><Plus size={16}/>{action}</Button>}</header>;
